  ('MEDICAL_KNOWLEDGE', (select id from public.knowledge_documents where title = 'HbA1c (glycated haemoglobin)'), 1, 'HbA1c can be unreliable in some situations, including certain anaemias, haemoglobin variants, recent blood transfusion, pregnancy, and kidney or liver disease, because these change how long red blood cells survive.', '[-0.054295413196086884,-0.043476104736328125,-0.015980159863829613,0.012969364412128925,-0.007546440698206425,-0.008774584159255028,-0.034290920943021774,0.07033327966928482,-0.038679346442222595,-0.016654884442687035,-0.06628530472517014,0.007325585000216961,-0.044355608522892,-0.029423879459500313,-0.06350138783454895,-0.01984483376145363,0.09358182549476624,-0.014352061785757542,-0.0373988077044487,-0.01499179471284151,-0.07001731544733047,0.03281574323773384,-0.03742962330579758,0.06988415122032166,-0.019910991191864014,-0.0608338937163353,-0.059858690947294235,0.051051463931798935,-0.049099940806627274,-0.07517988979816437,0.025500111281871796,-0.005097442772239447,-0.014343854039907455,-0.018524054437875748,-0.025986144319176674,0.02694832719862461,-0.03900760039687157,-0.05245174840092659,-0.023190679028630257,-0.04185373708605766,0.059257350862026215,0.019806906580924988,-0.048315320163965225,0.03878146782517433,-0.048408910632133484,-0.036883287131786346,0.026136532425880432,0.006391539238393307,-0.03596013784408569,0.04273149371147156,-0.04889272153377533,-0.003991526551544666,0.0051641338504850864,-0.0024708437267690897,0.06214345991611481,0.0021233614534139633,-0.09655852615833282,0.0699160099029541,0.055556297302246094,-0.01872570812702179,-0.08215145766735077,0.010709894821047783,0.04106207937002182,-0.05994367599487305,0.1014270931482315,0.02543303370475769,0.06527463346719742,-0.09224390983581543,0.0396742969751358,0.022655516862869263,-0.07024416327476501,-0.016194701194763184,-0.022842014208436012,0.07097318023443222,-0.025717666372656822,0.023130595684051514,-0.050720006227493286,-0.029455380514264107,0.05043211579322