-- Fasting plasma glucose
insert into public.knowledge_documents (title, category, body, citation) values
  ('Fasting plasma glucose', 'LAB_REFERENCE', 'Fasting plasma glucose measures the amount of glucose in the blood after at least eight hours without food or drink other than water. It is a snapshot rather than an average.

The American Diabetes Association describes these categories: below 100 mg/dL (5.6 mmol/L) is considered normal; 100 to 125 mg/dL (5.6 to 6.9 mmol/L) is the range described as impaired fasting glucose, or prediabetes; 126 mg/dL (7.0 mmol/L) or above, confirmed on a repeat test, is one of the criteria used for diagnosing diabetes.

Eating shortly before the test, illness and some medications including corticosteroids can raise the result, which is one reason a single value is confirmed before it is acted on.', 'American Diabetes Association — Standards of Care in Diabetes, Classification and Diagnosis')
