-- LDL cholesterol
insert into public.knowledge_documents (title, category, body, citation) values
  ('LDL cholesterol', 'LAB_REFERENCE', 'LDL stands for low-density lipoprotein. It is often called "bad cholesterol" because LDL particles carry cholesterol into the artery wall, where it contributes to the plaque build-up of atherosclerosis. Higher LDL levels over time are associated with higher cardiovascular risk at a population level.

Commonly cited categories for adults are: below 100 mg/dL described as optimal; 100 to 129 mg/dL near or above optimal; 130 to 159 mg/dL borderline high; 160 to 189 mg/dL high; and 190 mg/dL or above very high.

Modern guidelines set targets according to a person''s overall cardiovascular risk rather than by LDL alone, so the level that matters for one person is not the level that matters for another.', 'National Heart, Lung, and Blood Institute — ATP III guidelines on cholesterol')
