-- HDL cholesterol
insert into public.knowledge_documents (title, category, body, citation) values
  ('HDL cholesterol', 'LAB_REFERENCE', 'HDL stands for high-density lipoprotein and is often called "good cholesterol". HDL particles carry cholesterol away from tissues and back to the liver, and at a population level higher HDL is associated with lower cardiovascular risk.

Commonly cited thresholds describe HDL below 40 mg/dL in men and below 50 mg/dL in women as low, and 60 mg/dL or above as a level associated with lower risk.

Unlike LDL, raising HDL with medicines has not been shown to reduce cardiovascular events, so HDL is generally used as part of assessing risk rather than as a target to be treated on its own.', 'National Heart, Lung, and Blood Institute — ATP III guidelines on cholesterol')
