-- Total cholesterol and triglycerides
insert into public.knowledge_documents (title, category, body, citation) values
  ('Total cholesterol and triglycerides', 'LAB_REFERENCE', 'Total cholesterol is the combined measure of cholesterol carried in all lipoprotein particles. Commonly cited categories for adults are: below 200 mg/dL described as desirable; 200 to 239 mg/dL borderline high; and 240 mg/dL or above high.

Triglycerides are a different kind of fat carried in the blood. Commonly cited categories are: below 150 mg/dL normal; 150 to 199 mg/dL borderline high; 200 to 499 mg/dL high; and 500 mg/dL or above very high. Triglyceride results are strongly affected by recent food and alcohol, which is why the test is often taken fasting.

Because total cholesterol combines both LDL and HDL, it can be misleading on its own — a high HDL raises it without indicating higher risk.', 'National Heart, Lung, and Blood Institute — ATP III guidelines on cholesterol')
