-- Blood pressure readings
insert into public.knowledge_documents (title, category, body, citation) values
  ('Blood pressure readings', 'LAB_REFERENCE', 'A blood pressure reading has two numbers written as systolic over diastolic, for example 128/82 mm Hg. Systolic is the pressure while the heart contracts; diastolic is the pressure between beats.

The 2017 American College of Cardiology and American Heart Association guideline describes these categories for adults: normal is below 120 and below 80; elevated is 120 to 129 and below 80; stage 1 is 130 to 139 or 80 to 89; stage 2 is 140 or above, or 90 or above.

Blood pressure varies through the day and rises with stress, caffeine, pain and the act of being measured in a clinic. Guidelines generally require readings on more than one occasion, often including measurements taken at home, before categorising someone.', 'American College of Cardiology / American Heart Association — 2017 Guideline for High Blood Pressure in Adults')
on conflict (title) do update set
  category = excluded.category,
  body     = excluded.body,
  citation = excluded.citation;

