-- Type 2 diabetes
insert into public.knowledge_documents (title, category, body, citation) values
  ('Type 2 diabetes', 'CONDITION', 'Type 2 diabetes is a long-term condition in which blood glucose stays higher than the normal range, because the body''s tissues respond less well to insulin and the pancreas cannot fully compensate. It develops gradually and can be present for years without noticeable symptoms.

It is generally identified through blood tests — fasting plasma glucose, HbA1c, or an oral glucose tolerance test — with an abnormal result confirmed on a second occasion. Monitoring commonly includes periodic HbA1c, blood pressure, lipid profile, kidney function, and eye and foot checks.

Management usually combines eating patterns, physical activity and, where appropriate, medicines, all decided with a healthcare team who know the person''s circumstances.', 'American Diabetes Association — Standards of Care in Diabetes')
