-- High blood pressure (hypertension)
insert into public.knowledge_documents (title, category, body, citation) values
  ('High blood pressure (hypertension)', 'CONDITION', 'Hypertension is persistently raised blood pressure. It usually causes no symptoms, which is why it is often found during routine measurement rather than because someone feels unwell. Over years, sustained high blood pressure increases the risk of stroke, heart disease and kidney disease.

It is identified from repeated readings rather than a single measurement, and guidelines commonly describe confirming clinic readings with measurements taken at home or over 24 hours, because blood pressure is often higher in a clinical setting.

Management may involve changes to diet, physical activity, alcohol and salt intake, and medicines where a clinician judges them appropriate.', 'American College of Cardiology / American Heart Association — 2017 Guideline for High Blood Pressure in Adults')
on conflict (title) do update set
  category = excluded.category,
  body     = excluded.body,
  citation = excluded.citation;

